        const removed = payload.old as Partial<RealtimeReaction>;
        if (!removed.post_id || !removed.user_id) return;
        setPosts((current) => current.map((post) => post.id === removed.post_id
          ? { ...post, social_reactions: (post.social_reactions ?? []).filter((reaction) => reaction.user_id !== removed.user_id) }
          : post));
      })
      .on("postgres_changes", { event: "INSERT", schema: "public", table: "social_comments" }, (payload) => {
        const incoming = payload.new as RealtimeComment;
        setPosts((current) => current.map((post) => post.id === incoming.post_id && !(post.social_comments ?? []).some((comment) => comment.id === incoming.id)
          ? { ...post, social_comments: [...(post.social_comments ?? []), { id: incoming.id, author_id: incoming.author_id, body: incoming.body, created_at: incoming.created_at }] }
          : post));
      })
      .subscribe((status) => {
        if (status === "SUBSCRIBED") setRealtimeState("live");
        else if (status === "CHANNEL_ERROR" || status === "TIMED_OUT") setRealtimeState("error");
        else setRealtimeState("connecting");
      });
    return () => { void supabase.removeChannel(channel); };
  }, [capabilities.posts, supabase, userId]);

